  quiz:[
    ['Was beschreibt KI auf dieser Stufe am besten?',['ein Geist in einer Kiste','ein Programm, das aus Beispielen eine wahrscheinliche Antwort baut','ein launischer Taschenrechner','ein fehlerfreies Lexikon'],1,'KI erkennt Muster und schlägt eine wahrscheinliche Antwort vor. Kein Bewusstsein und kein fehlerfreies Nachschlagewerk.'],
    ['Was verbessert eine Anfrage am meisten?',['in Großbuchstaben schreiben','"mach es ordentlich" verlangen','Ziel, Kontext und Format','drohen, die App zu löschen'],2,'Ziel, Kontext und Format nehmen das Raten weg.'],
    ['Muss man sich bei KI bedanken?',['nicht nötig, aber menschlich ist okay','ja, sonst merkt sie es sich','nein, das stört die Antworten','nur an Feiertagen'],0,'Das Modell ist nicht beleidigt. Ein ruhiger Ton hilft aber dir.'],
    ['KI nennt selbstsicher eine Tatsache, die du nicht kanntest. Was tun?',['glauben, klang ja sicher','in einer verlässlichen Quelle prüfen','denselben Text noch mal fragen','beleidigt sein'],1,'Ein Modell kann selbstsicher erfinden. Wichtiges prüfen wir.'],
    ['Welche Aufgabe gehört eher zum Taschenrechner als zur KI?',['einen Café-Namen finden','1234 x 56 rechnen','eine Mail abmildern','ein Thema einfach erklären'],1,'Genaues Rechnen ist bei einem regelbasierten Programm sicherer.'],
    ['Was ist die Oberfläche einer KI?',['das Gehirn des Modells','die Hülle, über die du mit dem Modell sprichst','das Passwort des Netzes','eine Art Halluzination'],1,'Chat, App oder Sprachassistent sind die Hülle, das Modell steckt darin.'],
    ['Warum antwortet das Modell auf dieselbe Frage manchmal anders?',['es ist beleidigt','es wählt Wörter nach Wahrscheinlichkeit, mit etwas Zufall','es hat schlechte Laune','jemand hat die Antwort vertauscht'],1,'Das Modell wählt Fortsetzungen nach Wahrscheinlichkeit, daher variieren Antworten etwas.'],
    ['Wo ist KI für Einsteiger besonders nützlich?',['Entscheidungen für dich treffen','vom leeren Blatt starten und Gedanken ordnen','Passwörter speichern','den Arzt ersetzen'],1,'Entwürfe, Pläne und Erklärungen: Da spart sie am meisten Kraft.'],
    ['Was solltest du zu "erkläre Steuern" hinzufügen?',['mehr Ausrufezeichen','wer du bist und in welcher Form','zehnmal "bitte"','nichts, sie versteht schon'],1,'Kontext und Format machen die Antwort zu deiner, nicht zu einer allgemeinen.'],
    ['Wer ist verantwortlich, wenn du eine KI-Antwort verwendest?',['die KI','die Entwicklerfirma','du','niemand'],2,'Das Modell hilft, aber Entscheidung und Prüfung bleiben bei dir.']
  ]
